 public class ResumeDialog:Form {
  TextBox note,step,done;Label status;Button generate;CancellationTokenSource cancel;int revision;bool applying,busy;readonly Project project;readonly ApiConfig api;readonly AppData data;
  public ResumeDialog(Project p,ApiConfig config=null,AppData appData=null){project=p;api=config;data=appData??new AppData();UI.FormStyle(this,"接续卡 · AI 建议可以修改",650,570);Padding=new Padding(20);var root=UI.Table(1,40,28,72,28,72,28,64,72,50);root.Controls.Add(UI.Label("下一步不必重新想，可以先用建议。",15,true),0,0);note=UI.TextBox(true);note.Name="ResumeNote";note.MaxLength=500;note.Text=p.ResumeNote;step=UI.TextBox(true);step.Name="ResumeStep";step.MaxLength=500;step.Text=String.IsNullOrWhiteSpace(p.SmallStep)?TaskSupport.Next(p):p.SmallStep;done=UI.TextBox(true);done.Name="ResumeDone";done.MaxLength=500;done.Text=p.DoneWhen;root.Controls.Add(UI.Label("接续线索 / 建议（请确认符合实际）",9),0,1);root.Controls.Add(note,0,2);root.Controls.Add(UI.Label("下一步 · 2–5 分钟内能开始的动作",9),0,3);root.Controls.Add(step,0,4);root.Controls.Add(UI.Label("做到什么就可以结束？",9),0,5);root.Controls.Add(done,0,6);status=UI.Label("建议只填入这里，点击保存才写入任务；也可以直接手动修改。\nAI 会收到本任务信息、自述习惯和计时汇总；可能产生 API 费用。",9);status.AutoEllipsis=false;root.Controls.Add(status,0,7);generate=UI.Button("AI 生成建议",async()=>await Generate());root.Controls.Add(UI.Flow(UI.Button("保存接续卡",()=>{p.ResumeNote=note.Text.Trim();p.SmallStep=String.IsNullOrWhiteSpace(p.SmallStep)&&step.Text.Trim()==TaskSupport.Next(p)?"":step.Text.Trim();p.DoneWhen=done.Text.Trim();p.UpdatedUtc=DateTime.UtcNow;DialogResult=DialogResult.OK;Close();},true),generate,UI.Button("暂时不用",()=>Close())),0,8);Controls.Add(root);foreach(var box in new[]{note,step,done})box.TextChanged+=(s,e)=>{if(!applying)revision++;};Shown+=async(s,e)=>{if(config!=null&&!String.IsNullOrWhiteSpace(config.Model)&&data.AutoResumeSuggestions&&String.IsNullOrWhiteSpace(p.ResumeNote)&&String.IsNullOrWhiteSpace(p.SmallStep)&&String.IsNullOrWhiteSpace(p.DoneWhen))await Generate();};FormClosing+=(s,e)=>{if(cancel!=null)cancel.Cancel();};}
  public async Task Generate(){if(busy)return;if(api==null||String.IsNullOrWhiteSpace(api.Model)){status.Text="请先在设置中配置 API。当前建议仍可手动填写和保存。";return;}busy=true;generate.Enabled=false;int startedRevision=revision;cancel=new CancellationTokenSource();status.Text="正在生成建议（最多 60 秒）。你可以继续编辑；不会覆盖等待期间的修改。";try{var draft=new Project{Name=project.Name,NextStep=project.NextStep,SmallStep=step.Text,ResumeNote=note.Text,DoneWhen=done.Text,LastCheckpoint=project.LastCheckpoint,Stages=project.Stages};var values=await Planner.ResumeSuggestions(draft,data,api,cancel.Token);if(IsDisposed)return;if(!TryApplySuggestions(values,startedRevision)){status.Text="检测到你已经修改内容，本次 AI 结果未覆盖它们。需要时可重新生成。";return;}status.Text="AI 建议已填入，尚未保存。可以修改后再点击保存接续卡。";}catch(OperationCanceledException){if(!IsDisposed)status.Text="生成已取消或超时，原内容保留。";}catch(Exception){if(!IsDisposed)status.Text="暂时无法生成，请检查 API 或重试。原内容保留，仍可手动保存。";}finally{busy=false;if(!IsDisposed)generate.Enabled=true;cancel.Dispose();cancel=null;}}
  public bool TryApplySuggestions(string[] values,int expectedRevision){if(revision!=expectedRevision)return false;applying=true;try{note.Text=values[0];step.Text=values[1];done.Text=values[2];}finally{applying=false;}return true;}
 }
