  void LoadStages(List<Stage> stages){grid.Rows.Clear();foreach(var s in stages){int row=grid.Rows.Add(s.Done,s.Remaining,"",s.Title,s.Action);grid.Rows[row].Tag=s.Id;if(s.AllocatedSeconds>0)grid.Rows[row].Cells[2].Tag=s.AllocatedSeconds;}UpdateDurations();grid.CurrentCell=null;grid.ClearSelection();if(removeStage!=null)removeStage.Enabled=false;}
  int PlanMinutes(){if(mode.SelectedIndex==1)return (int)minutes.Value;if(original.PomodoroMinutes>0)return original.PomodoroMinutes;return appData==null?25:Math.Max(1,appData.FocusMinutes);}
  void UpdateDurations(){if(grid==null||grid.Columns["duration"]==null)return;updatingDurations=true;try{int total=PlanMinutes();for(int i=0;i<grid.Rows.Count;i++){int current,next=0;if(!Int32.TryParse(Convert.ToString(grid.Rows[i].Cells[1].Value),out current))continue;if(i+1<grid.Rows.Count)Int32.TryParse(Convert.ToString(grid.Rows[i+1].Cells[1].Value),out next);int seconds=grid.Rows[i].Cells[2].Tag is int?(int)grid.Rows[i].Cells[2].Tag:Math.Max(0,(int)Math.Round(total*60*Math.Max(0,current-next)/100.0));grid.Rows[i].Cells[2].Value=FocusEngine.Duration(seconds);}}finally{updatingDurations=false;}}
  void ApplyDuration(int row){if(row<0||row>=grid.Rows.Count)return;TimeSpan span;if(!TimeSpan.TryParse(Convert.ToString(grid.Rows[row].Cells[2].Value),out span)||span.TotalSeconds<0){UpdateDurations();return;}int total=Math.Max(60,PlanMinutes()*60),seconds=Math.Max(1,(int)Math.Round(span.TotalSeconds)),share=Math.Max(1,(int)Math.Round(seconds*100.0/total));int current=100;if(!Int32.TryParse(Convert.ToString(grid.Rows[row].Cells[1].Value),out current))current=100;updatingDurations=true;try{grid.Rows[row].Cells[2].Tag=seconds;if(row+1<grid.Rows.Count){int after=0;if(row+2<grid.Rows.Count)Int32.TryParse(Convert.ToString(grid.Rows[row+2].Cells[1].Value),out after);grid.Rows[row+1].Cells[1].Value=Math.Max(after,Math.Min(current,current-share));grid.Rows[row+1].Cells[2].Tag=null;}else{int upper=row==0?100:Convert.ToInt32(grid.Rows[row-1].Cells[1].Value);grid.Rows[row].Cells[1].Value=Math.Max(0,Math.Min(upper,share));}}finally{updatingDurations=false;}UpdateDurations();}
  class StageDrag{public ProjectDialog Owner;public int Index;}
  void RenumberStages(){for(int i=0;i<grid.Rows.Count;i++)grid.Rows[i].Cells[1].Value=100-(int)Math.Floor(90.0*i/Math.Max(1,grid.Rows.Count-1));UpdateDurations();}
  void AddStage(){if(grid.Rows.Count>=20){status.Text="最多20个子任务。";return;}grid.EndEdit();int index=grid.SelectedRows.Count==0?grid.Rows.Count:grid.SelectedRows[0].Index+1;grid.Rows.Insert(index,false,100,"","新子任务","");grid.Rows[index].Tag=Guid.NewGuid().ToString("N");RenumberStages();grid.CurrentCell=null;grid.ClearSelection();}
  void RemoveStage(){if(grid.SelectedRows.Count==0)return;grid.EndEdit();grid.Rows.RemoveAt(grid.SelectedRows[0].Index);RenumberStages();grid.CurrentCell=null;grid.ClearSelection();}
  void MoveStage(int direction){if(grid.SelectedRows.Count==0)return;int index=grid.SelectedRows[0].Index;MoveStageTo(index,index+direction);}
  void MoveStageTo(int index,int target){if(index<0||target<0||index>=grid.Rows.Count||target>=grid.Rows.Count||target==index)return;grid.EndEdit();var row=grid.Rows[index];grid.Rows.RemoveAt(index);grid.Rows.Insert(target,row);RenumberStages();grid.CurrentCell=grid.Rows[target].Cells[3];grid.Rows[target].Selected=true;}
  Project Draft(){return new Project{Id=original.Id,Name=name.Text.Trim(),NextStep=description.Text.Trim(),SmallStep=original.SmallStep,ResumeNote=original.ResumeNote,DoneWhen=original.DoneWhen,LastCheckpoint=original.LastCheckpoint,LastWorkedUtc=original.LastWorkedUtc,Enabled=original.Enabled,Completed=original.Completed,Deleted=original.Deleted,Challenge=mode.SelectedIndex==1,ChallengeMinutes=(int)minutes.Value,ChallengeMinutesCustomized=original.ChallengeMinutesCustomized||(mode.SelectedIndex==1&&(int)minutes.Value!=(original.PomodoroMinutes>0?original.PomodoroMinutes:(appData==null?25:appData.FocusMinutes))),PomodoroMinutes=original.PomodoroMinutes,AllowDistraction=original.AllowDistraction,AiEnabled=false,PlanSource=source};}
  List<Stage> ReadStages(){grid.EndEdit();var list=new List<Stage>();foreach(DataGridViewRow row in grid.Rows){if(row.IsNewRow)continue;int n;if(!Int32.TryParse(Convert.ToString(row.Cells[1].Value),out n))throw new InvalidOperationException("剩余百分比请填写整数。");if(row.Tag==null)row.Tag=Guid.NewGuid().ToString("N");list.Add(new Stage{Id=(string)row.Tag,Done=Convert.ToBoolean(row.Cells[0].Value??false),Remaining=n,AllocatedSeconds=row.Cells[2].Tag is int?(int)row.Cells[2].Tag:0,Title=Convert.ToString(row.Cells[3].Value).Trim(),Action=Convert.ToString(row.Cells[4].Value).Trim()});}return list;}
  async Task<bool> Generate(){
   if(busy)return false;if(String.IsNullOrWhiteSpace(name.Text)){status.Text="先填写任务名称。";return false;}
   if(String.IsNullOrWhiteSpace(api.Model)){status.Text="请先配置 API 的地址、模型和密钥；也可以先保存，稍后拆解。";return false;}
   busy=true;planTools.Enabled=false;generate.Enabled=false;bottom.Enabled=false;name.Enabled=false;description.Enabled=false;mode.Enabled=false;minutes.Enabled=false;grid.Enabled=false;cancel=new CancellationTokenSource();
   status.Text="正在请求 AI（最多等待 60 秒）。你可以关闭窗口取消。";
   try{var stages=await Planner.Generate(Draft(),api,cancel.Token,appData,readHistory.Checked);if(IsDisposed)return false;LoadStages(stages);source="AI 拆解";status.Text="方案已就绪（相同输入复用本次运行缓存）。检查后保存。";return true;}
   catch(OperationCanceledException){if(!IsDisposed)status.Text="请求已取消或超时；已填写内容保留，可以重试或先保存。";return false;}
   catch(Exception ex){if(!IsDisposed)status.Text=ex is System.Security.Cryptography.CryptographicException?"当前 Windows 用户无法解密密钥，请重新配置。":ex is System.Net.Http.HttpRequestException?"无法连接 API，请检查网络和接口地址。任务内容已保留。":ex.Message;return false;}
   finally{busy=false;if(!IsDisposed){planTools.Enabled=true;generate.Enabled=true;bottom.Enabled=true;name.Enabled=true;description.Enabled=true;mode.Enabled=true;minutes.Enabled=mode.SelectedIndex==1;grid.Enabled=true;}cancel.Dispose();cancel=null;}
  }
  void SaveTask(){
   if(busy)return;if(String.IsNullOrWhiteSpace(name.Text)){status.Text="请填写任务名称。";return;}

   try{var result=Draft();result.Stages=ReadStages();if(result.Stages.Count>0){string error=Planner.Validate(result.Stages);if(error!=null)throw new InvalidOperationException(error);}else if(result.Challenge){result.Stages=new List<Stage>{new Stage{Remaining=100,Title="开始任务",Action=result.NextStep},new Stage{Remaining=90,Title="检查方向",Action="当前的一小步是什么？"},new Stage{Remaining=70,Title="继续推进",Action="暂时放下无关事项，回到当前任务。"},new Stage{Remaining=50,Title="时间过半",Action="检查进度，先完成必要部分。"},new Stage{Remaining=30,Title="进入后半程",Action="缩小范围，优先做出可用结果。"},new Stage{Remaining=10,Title="收尾与保存",Action="整理已有成果，留时间保存。"}};result.PlanSource="默认提醒（可再 AI 拆解）";}
    if(result.PlanSource=="待拆解"||result.PlanSource=="待 AI 拆解")result.PlanSource="手动子任务";Result=result;DialogResult=DialogResult.OK;Close();
   }catch(Exception ex){status.Text=ex.Message;}
  }
